// v5: también pide edad y facultad (se escriben en la agenda del profesional al confirmar).
// v4 (US-9): recupera datos de la pestaña Borradores y entrega el borrador para guardarlo.
// Prepara y VALIDA la solicitud antes de avisar a la encargada y guardarla (US-1, US-2 y US-6).
// El teléfono y el JID vienen fijos del flujo principal (no del modelo): nadie registra a nombre de otro número.
// Si algo falta o no es válido, responde ok:false con la lista exacta, para que el agente pida SOLO eso
// y conserve lo demás (FR15).
const entrada = $('Entrada herramienta').first().json;
// US-9-AC-4 / FR15: si un intento anterior falló, se recuperan los datos guardados en la pestaña
// Borradores (máximo 48 horas). Lo que el estudiante acaba de dar siempre tiene prioridad.
const CAMPOS = ['nombre', 'codigo', 'tipo_documento', 'numero_documento', 'edad', 'programa', 'facultad', 'correo', 'telefono_contacto',
  'servicio', 'tipo_atencion', 'disponibilidad', 'fecha_solicitada', 'hora_solicitada', 'profesional_solicitado'];
let previo = {};
try {
  const b = $('Leer borrador').first().json;
  const guardado = DateTime.fromFormat(String(b.actualizado ?? ''), 'yyyy-MM-dd HH:mm', { zone: 'America/Bogota' });
  if (b.datos && guardado.isValid && $now.diff(guardado, 'hours').hours <= 48) previo = JSON.parse(b.datos);
} catch (e) { previo = {}; }
const i = { ...entrada };
for (const k of CAMPOS) if (!String(entrada[k] ?? '').trim() && String(previo[k] ?? '').trim()) i[k] = previo[k];
const borradorObj = {};
for (const k of CAMPOS) if (String(i[k] ?? '').trim()) borradorObj[k] = String(i[k]).trim();
const borrador = JSON.stringify(borradorObj);
const ZONA = 'America/Bogota';
const hoy = $now.setZone(ZONA).startOf('day');
const limpio = v => String(v ?? '').trim().replace(/\s+/g, ' ');
const sinTildes = s => limpio(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

// Servicios habilitados (US-2-AC-1). Deben coincidir con los del prompt y con las carpetas de Drive.
const SERVICIOS = { psicologia: 'psicología', medicina: 'medicina', odontologia: 'odontología' };
// Tipos de documento aceptados (pendiente de confirmar con Erika: decisión D4).
const TIPOS = [
  { tipo: 'CC',  claves: ['cc', 'cedula de ciudadania', 'cedula'],            patron: /^\d{6,10}$/,       ayuda: 'de 6 a 10 dígitos' },
  { tipo: 'TI',  claves: ['ti', 'tarjeta de identidad', 'tarjeta'],           patron: /^\d{10,11}$/,      ayuda: 'de 10 u 11 dígitos' },
  { tipo: 'CE',  claves: ['ce', 'cedula de extranjeria', 'extranjeria'],      patron: /^[a-z0-9]{5,12}$/i, ayuda: 'de 5 a 12 letras o números' },
  { tipo: 'PPT', claves: ['ppt', 'permiso por proteccion temporal', 'permiso'], patron: /^\d{6,10}$/,     ayuda: 'de 6 a 10 dígitos' },
  { tipo: 'PA',  claves: ['pa', 'pasaporte'],                                  patron: /^[a-z0-9]{5,12}$/i, ayuda: 'de 5 a 12 letras o números' },
];

const problemas = [];
const nombre = limpio(i.nombre);
if (nombre.split(' ').filter(p => /\p{L}{2,}/u.test(p)).length < 2) problemas.push('nombre completo (nombre y apellido)');

const codigo = limpio(i.codigo).replace(/[\s.-]/g, '');
if (!/^\d{6,15}$/.test(codigo)) problemas.push('código estudiantil (solo números, de 6 a 15 dígitos)');

const tipoTxt = sinTildes(i.tipo_documento).replace(/\./g, '');
const tipo = TIPOS.find(t => t.claves.some(k => tipoTxt === k || tipoTxt.startsWith(k + ' ')));
if (!tipo) problemas.push('tipo de documento (CC, TI, CE, PPT o pasaporte)');

const numero = limpio(i.numero_documento).replace(/[\s.-]/g, '');
if (!numero) problemas.push('número de documento');
else if (tipo && !tipo.patron.test(numero)) problemas.push(`número de documento (para ${tipo.tipo} debe tener ${tipo.ayuda})`);
// US-1-AC-3: el código y el documento son datos distintos; uno no reemplaza al otro.
if (numero && codigo && numero === codigo) problemas.push('número de documento (es igual al código estudiantil: se necesitan los dos por separado)');

const edadTxt = limpio(i.edad).replace(/\D/g, '');
const edad = Number(edadTxt);
if (!edadTxt || edad < 14 || edad > 90) problemas.push('edad (en años, solo el número)');

const programa = limpio(i.programa);
if (programa.length < 3) problemas.push('programa académico');

const facultad = limpio(i.facultad);
if (facultad.length < 3) problemas.push('facultad');

const correo = limpio(i.correo).toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(correo)) problemas.push('correo electrónico (ej. nombre@unicauca.edu.co)');

const servicioClave = Object.keys(SERVICIOS).find(k => sinTildes(i.servicio).includes(k));
if (!servicioClave) problemas.push('servicio (psicología, medicina u odontología)');

// US-6: tipo de atención, necesario para saber si la cita tiene costo.
const TIPOS_ATENCION = { primera: 'primera_vez', seguimiento: 'seguimiento', control: 'control' };
const tipoAtencionTxt = sinTildes(i.tipo_atencion);
const tipoAtencion = Object.entries(TIPOS_ATENCION).find(([k]) => tipoAtencionTxt.includes(k))?.[1];
if (!tipoAtencion) problemas.push('tipo de atención (primera vez, seguimiento o control)');

// Teléfono de contacto: opcional. Si no lo dan, se usa el mismo WhatsApp.
let telefonoContacto = limpio(i.telefono_contacto).replace(/\D/g, '');
if (telefonoContacto) {
  if (/^3\d{9}$/.test(telefonoContacto)) telefonoContacto = '57' + telefonoContacto;
  if (!/^573\d{9}$/.test(telefonoContacto)) problemas.push('teléfono de contacto (celular colombiano de 10 dígitos)');
}

if (limpio(i.whatsapp_jid).endsWith('@lid') && !telefonoContacto) problemas.push('teléfono de contacto (celular de 10 dígitos: no pudimos ver tu número de WhatsApp)');

// US-4: si viene un horario elegido, su fecha debe ser posterior a hoy.
const fecha = limpio(i.fecha_solicitada);
if (fecha) {
  const f = DateTime.fromISO(fecha, { zone: ZONA });
  if (!f.isValid || f.startOf('day') <= hoy)
    problemas.push(`horario (la fecha debe ser posterior a hoy, ${hoy.setLocale('es').toFormat("d 'de' LLLL")}; vuelve a consultar horarios)`);
}

if (problemas.length)
  return [{ json: { ok: false, faltantes: problemas, borrador, campos_guardados: Object.keys(borradorObj),
    mensaje: `Faltan o no son válidos estos datos: ${problemas.join('; ')}. Pide SOLO esos datos, en un solo mensaje, y conserva los demás que ya dio.` } }];

const ABC = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';   // sin 0/O ni 1/I para dictarlo sin errores
let cod = '';
for (let k = 0; k < 6; k++) cod += ABC[Math.floor(Math.random() * ABC.length)];
const telefono = limpio(i.telefono).replace(/\D/g, '');
return [{ json: {
  ok: true,
  borrador,
  id: 'UCU-' + cod,
  fecha_solicitud: $now.setZone(ZONA).toFormat('dd/MM/yyyy HH:mm'),
  telefono, whatsapp_jid: limpio(i.whatsapp_jid),
  nombre, codigo, programa, edad: edadTxt ? edad : '', facultad,
  tipo_documento: tipo.tipo, numero_documento: numero.toUpperCase(), correo,
  telefono_contacto: telefonoContacto || telefono,
  servicio: SERVICIOS[servicioClave], tipo_atencion: tipoAtencion, disponibilidad: limpio(i.disponibilidad),
  fecha_solicitada: fecha, hora_solicitada: limpio(i.hora_solicitada),
  profesional_solicitado: limpio(i.profesional_solicitado),
} }];

