parameters.jsCode:
// US-8 · Respuesta para el agente después de intentar guardar la solicitud.
// AC-1: trae servicio, profesional, fecha y hora solicitados. AC-2: dice si queda RECIBIDA o PENDIENTE.
// AC-3 / US-9-AC-2: este nodo solo corre si Guardar solicitud funcionó. Si falló, su salida de error
// va a "Respuesta registro fallido" y el agente NO puede decir que quedó registrada.
const d = $('Decidir registro').first().json;
const ZONA = 'America/Bogota';
const f = DateTime.fromISO(String(d.fecha_solicitada ?? ''), { zone: ZONA });
const h = String(d.hora_solicitada ?? '').match(/^(\d{1,2}):(\d{2})/);
const horaTxt = h ? `${(+h[1] % 12) || 12}:${h[2]} ${+h[1] < 12 ? 'a. m.' : 'p. m.'}` : '';
const cuando = f.isValid ? f.setLocale('es').toFormat("cccc d 'de' LLLL") + (horaTxt ? `, ${horaTxt}` : '') : '';
const categoria = d.estado === 'PENDIENTE_VALIDACION' || (d.requiere_pago === 'SI') || d.requiere_pago === 'POR_CONFIRMAR' ? 'PENDIENTE' : 'RECIBIDA';

const partes = [`Solicitud ${d.id} registrada (${categoria}): ${d.servicio}${d.profesional_solicitado ? ', profesional solicitado ' + d.profesional_solicitado : ''}${cuando ? ', horario solicitado ' + cuando : ''}. Repite estos datos al estudiante.`];
if (d.estado === 'PENDIENTE_VALIDACION')
  partes.push('No fue posible verificar el horario en este momento: queda PENDIENTE DE VALIDACIÓN y Salud Integral lo revisará. Dilo así; no es una confirmación.');
else
  partes.push('El horario elegido seguía disponible al registrar. Es una solicitud RECIBIDA, no una cita confirmada: Salud Integral asignará el profesional y confirmará por este chat.');
if (d.requiere_pago === 'NO')
  partes.push('Según las reglas de Salud Integral, esta atención no tiene costo.');
else if (d.requiere_pago === 'SI')
  partes.push(`Esta atención requiere pago${d.valor_pago ? ' de ' + d.valor_pago : ''}. Salud Integral generará el recibo y lo enviará al correo del estudiante. Cuando pague, debe enviar por este chat una foto o PDF del comprobante. La cita solo se confirma cuando Salud Integral valide el pago.${d.instrucciones_pago ? ' ' + d.instrucciones_pago : ''}`);
else if (d.requiere_pago !== 'NO')
  partes.push('Salud Integral le indicará si esta atención tiene algún costo. No menciones valores.');
const mensajeFinal = partes.join(' ').replace(/\.\. /g, '. ');
return [{ json: { ok: true, id: d.id, categoria, estado: d.estado, servicio: d.servicio,
  profesional: d.profesional_solicitado, cuando, requiere_pago: d.requiere_pago, estado_pago: d.estado_pago,
  valor_pago: d.valor_pago, mensaje: mensajeFinal } }];

// Verifica que la solicitud exista, que pertenezca a ESTE número y que todavía se pueda cancelar.
// US-7: RECHAZADA, CANCELADA y CERRADA son estados finales; CANCELACION_SOLICITADA ya está en trámite.
const i = $('Entrada herramienta').first().json;
const buscado = String(i.id_solicitud ?? '').trim().toUpperCase();
const tel = String(i.telefono ?? '').replace(/\D/g, '');
const fila = $input.all().map(x => x.json)
  .find(r => String(r.id ?? '').trim().toUpperCase() === buscado);
const no = motivo => [{ json: { ok: false, mensaje: motivo } }];
if (!buscado || !fila) return no('No encontré una solicitud con ese código.');
if (String(fila.telefono ?? '').replace(/\D/g, '') !== tel)
  return no('Esa solicitud no está asociada a este número de WhatsApp.');
const estado = String(fila.estado ?? '').trim().toUpperCase();
if (estado === 'CANCELADA' || estado === 'CANCELACION_SOLICITADA')
  return no('Esa solicitud ya estaba cancelada o en proceso de cancelación.');
if (estado === 'RECHAZADA')
  return no('Esa solicitud fue rechazada por Salud Integral, así que no hay nada que cancelar. Si necesitas una cita, puedo ayudarte con una solicitud nueva.');
if (estado === 'CERRADA')
  return no('Esa cita ya pasó y la solicitud está cerrada. Si necesitas otra cita, puedo ayudarte con una solicitud nueva.');
return [{ json: { ok: true, ...fila } }];

