parameters.jsCode:
// US-9-AC-4 · Cuando faltan datos, responde qué falta y confirma que lo demás quedó guardado (Borradores).
const p = $('Preparar solicitud').first().json;
return [{ json: { ok: false, faltantes: p.faltantes, datos_guardados: p.campos_guardados,
  mensaje: (p.mensaje || 'Faltan datos.') + ' Los demás datos quedaron guardados: no los vuelvas a pedir.' } }];

// US-4 · Valida el servicio y la fecha ANTES de consultar la agenda.
// US-2 · Deja pasar la preferencia de profesional (opcional) para filtrar los horarios.
// US-5 · Modo "verificar": la usa el registro para revisar, justo antes de guardar, que el horario
//        elegido (fecha_solicitada, hora_solicitada, profesional_solicitado) siga libre.
// No tiene IDs de carpetas: la carpeta del mes se busca sola más adelante (ver "Elegir carpetas del mes").
const ZONA = 'America/Bogota';
const SERVICIOS = ['psicologia', 'medicina', 'odontologia'];

const i = $('Entrada herramienta').first().json;
const hoy = DateTime.now().setZone(ZONA).startOf('day');
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const no = mensaje => [{ json: { ok: false, mensaje } }];
const bonito = d => d.setLocale('es').toFormat("cccc d 'de' LLLL");

const servicio = SERVICIOS.find(k => norm(i.servicio).includes(k));
if (!servicio) return no('Servicio no reconocido. Debe ser psicología, medicina u odontología.');

const verificar = norm(i.accion) === 'verificar';
const horaVerificar = String(i.hora_solicitada ?? '').trim().match(/^(\d{1,2}):(\d{2})/);
if (verificar && (!String(i.fecha_solicitada ?? '').trim() || !horaVerificar))
  return no('No hay un horario elegido para verificar.');

// Sin fecha = buscar desde mañana. La fecha debe ser posterior a hoy (FR5).
let desde = hoy.plus({ days: 1 });
const pedida = String(verificar ? i.fecha_solicitada : i.fecha_desde ?? '').trim();
if (pedida) {
  const f = DateTime.fromISO(pedida, { zone: ZONA });
  if (!f.isValid) return no('No entendí la fecha. Pide una fecha concreta, por ejemplo "12 de noviembre".');
  if (f.startOf('day') <= hoy)
    return no(`La cita debe ser para una fecha posterior a hoy (${bonito(hoy)}). Pide otra fecha a partir de ${bonito(hoy.plus({ days: 1 }))}.`);
  desde = f.startOf('day');
}

const fr = norm(i.franja);
return [{ json: {
  ok: true,
  modo: verificar ? 'verificar' : 'consultar',
  servicio,
  desde: desde.toISODate(),
  franja: verificar ? '' : fr.startsWith('m') ? 'mañana' : fr.startsWith('t') ? 'tarde' : '',
  // Al verificar se buscan horarios de TODOS los profesionales, para poder ofrecer alternativas;
  // el profesional elegido se compara después, en "Armar respuesta".
  profesional: verificar ? '' : String(i.profesional ?? '').trim(),   // vacío = cualquier profesional
  hora_verificar: verificar ? horaVerificar[1].padStart(2, '0') + ':' + horaVerificar[2] : '',
  profesional_verificar: verificar ? String(i.profesional_solicitado ?? '').trim() : '',
} }];

// Variante automática: no hay IDs por año.
// "Leer configuración" trae una sola fila: clave = carpeta_raiz_id | valor = <ID de la carpeta raíz>.
// "Listar carpetas de años" trae las subcarpetas de la raíz; aquí se reconoce el año por el NOMBRE
// ("2026", "Año 2027", "AGENDAS 2028"...). Se ignoran copias y respaldos.
const MESES_A_CONSULTAR = 2;
const ZONA = 'America/Bogota';
const IGNORAR = /\b(COPIA|COPY|RESPALDO|BACKUP|BORRADOR|OLD|ANTIGUO)\b/;
const c = $('Validar consulta').first().json;
const raiz = String($('Leer configuración').first().json.valor ?? '').trim();
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase()
  .replace(/[^A-Z0-9]+/g, ' ').trim();
const no = mensaje => [{ json: { ok: false, mensaje } }];

if (!raiz)
  return no('No pude consultar la agenda por un problema de configuración. No ofrezcas horarios; registra la solicitud para que Salud Integral la gestione.');

const desde = DateTime.fromISO(c.desde, { zone: ZONA }).startOf('month');
const meses = Array.from({ length: MESES_A_CONSULTAR }, (_, k) => desde.plus({ months: k }));
const anios = new Set(meses.map(d => d.year));

const carpetas = $input.all().map(x => x.json)
  .filter(f => f.id && f.name && !IGNORAR.test(norm(f.name)))
  .map(f => ({ id: f.id, anio: Number(norm(f.name).split(' ').find(p => /^20\d{2}$/.test(p))) }))
  .filter(f => anios.has(f.anio));

if (!carpetas.length)
  return no(`Todavía no hay agenda publicada para ${desde.setLocale('es').toFormat("LLLL 'de' yyyy")}. Ofrece buscar en otra fecha o registrar la solicitud para que Salud Integral la gestione.`);

const q = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
return [{ json: {
  ok: true,
  anio_por_carpeta: Object.fromEntries(carpetas.map(x => [x.id, x.anio])),
  meses_buscados: meses.map(d => d.year * 100 + d.month),
  query_meses: `(${carpetas.map(x => `'${q(x.id)}' in parents`).join(' or ')}) and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
} }];

// Dentro de las carpetas de año, encuentra las de los meses que hay que consultar, por su NOMBRE.
// Acepta "NOVIEMBRE", "Noviembre", "NOV", "11", "11_NOVIEMBRE", "NOVIEMBRE_2026"...
// El año lo pone la carpeta padre; si el nombre trae otro año, se ignora la carpeta.
const MESES = { ENERO: 1, FEBRERO: 2, MARZO: 3, ABRIL: 4, MAYO: 5, JUNIO: 6, JULIO: 7, AGOSTO: 8,
  SEPTIEMBRE: 9, SETIEMBRE: 9, OCTUBRE: 10, NOVIEMBRE: 11, DICIEMBRE: 12 };
const ABREV = { ENE: 1, FEB: 2, MAR: 3, ABR: 4, MAY: 5, JUN: 6, JUL: 7, AGO: 8, SEP: 9, SET: 9, OCT: 10, NOV: 11, DIC: 12 };
const IGNORAR = /\b(COPIA|COPY|RESPALDO|BACKUP|BORRADOR|OLD|ANTIGUO)\b/;
const ZONA = 'America/Bogota';

const a = $('Elegir carpetas del año').first().json;
const c = $('Validar consulta').first().json;
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase()
  .replace(/[^A-Z0-9]+/g, ' ').trim();

function mesDeNombre(nombre) {
  const palabras = norm(nombre).split(' ');
  const anio = palabras.find(p => /^20\d{2}$/.test(p));
  const mes = palabras.map(p => MESES[p]).find(Boolean)
    ?? palabras.map(p => ABREV[p]).find(Boolean)
    ?? palabras.filter(p => /^\d{1,2}$/.test(p)).map(Number).find(n => n >= 1 && n <= 12);
  return mes ? { mes, anio: anio ? Number(anio) : null } : null;
}

const quiero = new Set(a.meses_buscados);
const elegidas = [];
for (const it of $input.all()) {
  const f = it.json;
  if (!f.id || !f.name || IGNORAR.test(norm(f.name))) continue;
  const padre = (f.parents ?? []).find(p => a.anio_por_carpeta[p]);
  const anioPadre = padre ? a.anio_por_carpeta[padre] : null;
  const m = mesDeNombre(f.name);
  if (!m || !anioPadre) continue;
  if (m.anio && m.anio !== anioPadre) continue;
  if (quiero.has(anioPadre * 100 + m.mes)) elegidas.push(f);
}

if (!elegidas.length) {
  const d = DateTime.fromISO(c.desde, { zone: ZONA });
  return [{ json: { ok: false, mensaje: `Todavía no hay agenda publicada para ${d.setLocale('es').toFormat("LLLL 'de' yyyy")}. Ofrece buscar en otra fecha o registrar la solicitud para que Salud Integral la gestione.` } }];
}
const q = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
return [{ json: {
  ok: true,
  carpetas_mes: elegidas.map(f => f.name),
  query_servicios: `(${elegidas.map(f => `'${q(f.id)}' in parents`).join(' or ')}) and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
} }];

// De las subcarpetas de los meses encontrados, se queda con las del servicio pedido.
// Tolera mayúsculas, tildes y espacios: "PSICOLOGIA", "Psicología", "MEDICINA GENERAL", "Odontología".
const RAIZ_SERVICIO = { psicologia: 'PSICOLOG', medicina: 'MEDICINA', odontologia: 'ODONTOLOG' };
const c = $('Validar consulta').first().json;
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const raizNombre = RAIZ_SERVICIO[c.servicio];

const carpetas = $input.all().map(x => x.json).filter(f => f.id && norm(f.name).includes(raizNombre));
if (!carpetas.length)
  return [{ json: { ok: false, mensaje: `Todavía no hay agenda de ${c.servicio} publicada para esas fechas. Ofrece buscar en otra fecha o registrar la solicitud para que Salud Integral la gestione.` } }];

const q = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
return [{ json: {
  ok: true,
  query_agendas: `(${carpetas.map(f => `'${q(f.id)}' in parents`).join(' or ')}) and trashed = false and (mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' or mimeType = 'application/vnd.google-apps.spreadsheet')`,
} }];

// El nodo Compression solo abre archivos con extensión .zip. Un .xlsx ES un .zip por dentro,
// así que aquí solo se cambia la etiqueta de la extensión de la copia descargada.
// El archivo de Erika en Drive no se toca.
return $input.all().map(item => {
  if (item.binary?.data) {
    item.binary.data.fileExtension = 'zip';
    item.binary.data.fileName = String(item.binary.data.fileName ?? 'agenda') + '.zip';
  }
  return item;
});

// US-3 · Lee las agendas de Erika directamente desde el Excel (.xlsx) y devuelve solo los horarios LIBRES.
// Llega un item por profesional con las partes internas del .xlsx ya descomprimidas (nodo Compression).
// Un .xlsx es un ZIP de archivos XML: aquí se leen los valores de las celdas Y las celdas combinadas,
// sin convertir ni modificar el archivo original.
//   - LIBRE: la fila del horario no tiene nada escrito en A:E.
//   - OCUPADO: hay un estudiante (o cualquier texto) en A:E.
//   - BLOQUEADO: la fila está dentro de una combinación de celdas que abarca A:E ("OCUPADO", "CONGRESO"...).
// En la tabla de la tarde las horas se escriben sin am/pm: "2:00" se interpreta como 14:00.
// US-2: devuelve también los profesionales del servicio y, si el estudiante pidió uno, filtra por él.
// US-5: ya no elige las 6 opciones: entrega TODOS los horarios libres (candidatos) al nodo
//       "Armar respuesta", que descuenta los apartados por otras solicitudes y arma la respuesta.
const ZONA = 'America/Bogota';
const MESES = { ENERO: 1, FEBRERO: 2, MARZO: 3, ABRIL: 4, MAYO: 5, JUNIO: 6, JULIO: 7, AGOSTO: 8,
  SEPTIEMBRE: 9, SETIEMBRE: 9, OCTUBRE: 10, NOVIEMBRE: 11, DICIEMBRE: 12 };

const c = $('Validar consulta').first().json;
const ahora = DateTime.now().setZone(ZONA);
const manana = ahora.startOf('day').plus({ days: 1 });   // nunca hoy ni antes (FR5)
const desde = DateTime.fromISO(c.desde, { zone: ZONA }).startOf('day');
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
const titulo = s => String(s).toLowerCase().replace(/(^|\s)\S/g, t => t.toUpperCase());

// ---------- Lectura del XML del Excel ----------
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
const dec = s => String(s).replace(/&(#x[0-9a-fA-F]+|#\d+|amp|lt|gt|quot|apos);/g, (m, e) =>
  e[0] !== '#' ? ENT[e] : String.fromCodePoint(e[1] === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10)));
const textoDe = xml => [...String(xml).matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g)].map(m => dec(m[1])).join('');
const atributo = (attrs, nombre) => (attrs.match(new RegExp('(?:^|\\s)' + nombre + '="([^"]*)"')) ?? [])[1];
const columna = ref => [...ref.match(/^[A-Z]+/)[0]].reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0) - 1;
const filaDe = ref => Number(ref.match(/\d+$/)[0]) - 1;
const base = p => String(p).split('/').pop();

async function leerLibro(idx, binary) {
  // Partes del ZIP por ruta (xl/workbook.xml, xl/worksheets/sheet1.xml, ...)
  const partes = {};
  for (const [clave, meta] of Object.entries(binary ?? {})) {
    const ruta = [meta.directory, meta.fileName].filter(Boolean).join('/').replace(/^\/+/, '');
    partes[ruta] = clave;
  }
  const buscar = ruta => partes[ruta] ?? Object.entries(partes).find(([r]) => base(r) === base(ruta))?.[1];
  const leer = async ruta => {
    const clave = buscar(ruta);
    return clave ? (await this.helpers.getBinaryDataBuffer(idx, clave)).toString('utf8') : '';
  };

  const workbook = await leer('xl/workbook.xml');
  if (!workbook) return [];
  const rels = await leer('xl/_rels/workbook.xml.rels');
  const destino = {};
  for (const m of rels.matchAll(/<Relationship\b([^>]*)\/?>/g))
    destino[atributo(m[1], 'Id')] = atributo(m[1], 'Target');
  const compartidos = [...(await leer('xl/sharedStrings.xml')).matchAll(/<si>([\s\S]*?)<\/si>/g)].map(m => textoDe(m[1]));

  const hojas = [];
  for (const m of workbook.matchAll(/<sheet\b([^>]*)\/?>/g)) {
    const nombre = dec(atributo(m[1], 'name') ?? '');
    const objetivo = destino[atributo(m[1], 'r:id')] ?? '';
    const xml = await leer(objetivo.startsWith('/') ? objetivo.slice(1) : 'xl/' + objetivo);
    if (!xml) continue;
    const filas = [];
    for (const cm of xml.matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)) {
      const ref = atributo(cm[1], 'r');
      if (!ref) continue;
      const tipo = atributo(cm[1], 't') ?? 'n';
      const cuerpo = cm[2] ?? '';
      const v = (cuerpo.match(/<v>([\s\S]*?)<\/v>/) ?? [])[1];
      let valor = '';
      if (tipo === 's') valor = compartidos[Number(v)] ?? '';
      else if (tipo === 'inlineStr') valor = textoDe(cuerpo);
      else if (tipo === 'str' || tipo === 'e') valor = dec(v ?? '');
      else if (v !== undefined && v !== '') valor = Number(v);
      const r = filaDe(ref), col = columna(ref);
      (filas[r] ??= [])[col] = typeof valor === 'string' ? valor.trim() : valor;
    }
    const combinadas = [...xml.matchAll(/<mergeCell\b[^>]*ref="([A-Z]+\d+):([A-Z]+\d+)"/g)].map(mm => ({
      r0: filaDe(mm[1]), r1: filaDe(mm[2]), c0: columna(mm[1]), c1: columna(mm[2]),
    }));
    hojas.push({ nombre, filas, combinadas });
  }
  return hojas;
}

// Hora de la columna F: número de Excel (fracción del día) o texto "2:00".
function horaDe(v) {
  if (typeof v === 'number' && v >= 0 && v < 1) { const min = Math.round(v * 1440); return [Math.floor(min / 60), min % 60]; }
  const m = String(v ?? '').match(/^(\d{1,2}):(\d{2})/);
  return m ? [Number(m[1]), Number(m[2])] : null;
}

// ---------- Recorrido de cada agenda ----------
const cupos = [];
const items = $input.all();
for (let idx = 0; idx < items.length; idx++) {
  const hojas = await leerLibro.call(this, idx, items[idx].binary);
  const archivo = String(items[idx].json?.name ?? '').replace(/\.xlsx$/i, '').replace(/_/g, ' ');
  for (const hoja of hojas) {
    const celda = (r, col) => hoja.filas[r]?.[col] ?? '';
    const texto = (r, col) => String(celda(r, col)).trim();

    // Filas tapadas por una combinación que cubre las columnas A a E.
    const bloqueadas = new Map();
    for (const m of hoja.combinadas)
      if (m.c0 === 0 && m.c1 >= 4)
        for (let r = m.r0; r <= m.r1; r++) bloqueadas.set(r, texto(m.r0, 0) || 'OCUPADO');

    let profesional = '', anio = null, mes = null, dia = null, tabla = 0;
    for (let r = 0; r < hoja.filas.length; r++) {
      const A = norm(texto(r, 0)), E = norm(texto(r, 4)), F = norm(texto(r, 5));
      // "Psicólogo:  CAROLINA ARIAS" (o Médico:, Odontóloga:)
      if (!profesional && A.includes(':') && /(PSICOLOG|MEDIC|ODONTOLOG|PROFESIONAL)/.test(A))
        profesional = texto(r, 0).split(':').slice(1).join(':').trim();
      // Fila de fecha: E = "Fecha: NOVIEMBRE // 2026", F = "Dia:", y el día en G (texto "MARTES 3", número 3 o fecha)
      if (E.startsWith('FECHA') && F.startsWith('DIA')) {
        const mesTxt = Object.keys(MESES).find(k => E.includes(k));
        mes = mesTxt ? MESES[mesTxt] : null;
        anio = Number(E.match(/(20\d{2})/)?.[1] ?? ahora.year);
        dia = null;
        for (const col of [6, 7, 8]) {
          const v = celda(r, col);
          if (typeof v === 'number' && v > 20000) {           // una fecha real de Excel
            const d = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONA }).plus({ days: Math.floor(v) });
            anio = d.year; mes = d.month; dia = d.day; break;
          }
          const n = String(v).match(/\b(\d{1,2})\b/);
          if (n) { dia = Number(n[1]); break; }
        }
        if (!dia) dia = Number(texto(r, 5).match(/\b(\d{1,2})\b/)?.[1] ?? 0) || null;
        tabla = 0;
        continue;
      }
      if (F === 'HORA') { tabla++; continue; }          // 1 = mañana, 2 = tarde
      const h = horaDe(celda(r, 5));
      if (!h || !mes || !dia || tabla === 0) continue;
      let [hora, minuto] = h;
      if (tabla >= 2 && hora < 12) hora += 12;
      const fecha = DateTime.fromObject({ year: anio, month: mes, day: dia, hour: hora, minute: minuto }, { zone: ZONA });
      if (!fecha.isValid) continue;
      let estado = 'LIBRE';
      if (bloqueadas.has(r)) estado = 'BLOQUEADO';
      else if ([0, 1, 2, 3, 4].some(col => texto(r, col))) estado = 'OCUPADO';
      cupos.push({ fecha, estado, profesional: titulo(profesional || archivo) });
    }
  }
}

if (!cupos.length)
  return [{ json: { ok: false, mensaje: 'No pude leer la agenda de este servicio. No ofrezcas horarios; pide que lo intente más tarde o registra la solicitud para que Salud Integral la gestione.' } }];

// Si un mismo profesional aparece en dos archivos (por ejemplo un .xlsx y su copia en Sheets),
// gana el estado más restrictivo: nunca se ofrece un horario que alguna copia marca como tomado.
const PESO = { LIBRE: 0, OCUPADO: 1, BLOQUEADO: 2 };
const unicos = new Map();
for (const x of cupos) {
  const k = norm(x.profesional) + '|' + x.fecha.toISO();
  if (!unicos.has(k) || PESO[x.estado] > PESO[unicos.get(k).estado]) unicos.set(k, x);
}

// US-2-AC-2: profesionales que atienden este servicio (según las agendas leídas).
const profesionales = [...new Set([...unicos.values()].map(x => x.profesional))].sort();
// Preferencia opcional: basta con una parte del nombre ("Carolina", "Vasquez").
const pref = norm(c.profesional ?? '').split(' ').filter(p => p.length >= 3);
const coincide = x => !pref.length || pref.every(p => norm(x.profesional).includes(p));
if (pref.length && !profesionales.some(nombre => coincide({ profesional: nombre })))
  return [{ json: { ok: true, servicio: c.servicio, desde: c.desde, profesionales, candidatos: [],
    mensaje_sin_resultados: `No encontré a "${c.profesional}" en las agendas de ${c.servicio}. Atienden: ${profesionales.join(', ')}. Pregunta si quiere a otro profesional o cualquiera.` } }];

const candidatos = [...unicos.values()]
  .filter(x => x.estado === 'LIBRE' && x.fecha >= desde && x.fecha >= manana)
  .filter(coincide)
  .filter(x => !c.franja || (c.franja === 'mañana' ? x.fecha.hour < 12 : x.fecha.hour >= 12))
  .sort((a, b) => a.fecha.toMillis() - b.fecha.toMillis())
  .map(x => ({
    fecha: x.fecha.toISODate(),
    hora: x.fecha.toFormat('HH:mm'),
    texto: x.fecha.setLocale('es').toFormat("cccc d 'de' LLLL, h:mm a"),
    profesional: x.profesional,
  }));

return [{ json: {
  ok: true,
  servicio: c.servicio,
  desde: c.desde,
  franja: c.franja || 'cualquiera',
  profesional: c.profesional || 'cualquiera',
  profesionales,
  candidatos,
} }];

// v2 (US-9): cancelaciones en trámite siguen apartadas; sin horarios sugiere otra fecha.
// US-3 / US-5 · Último paso de la rama de horarios.
// Recibe las filas de la hoja Solicitudes (nodo "Leer solicitudes activas") y los horarios libres de las
// agendas ("Interpretar agenda"). Un horario que ya eligió otra solicitud activa queda APARTADO y no se
// ofrece, aunque Erika todavía no lo haya escrito en su agenda.
//   - modo "consultar": devuelve hasta 6 opciones libres y no apartadas.
//   - modo "verificar": responde si el horario elegido sigue disponible (US-5-AC-1) y, si no, ofrece
//     otras opciones (US-5-AC-2). Si algo no se pudo leer, responde verificado:false (US-5-AC-3).
const ZONA = 'America/Bogota';
const MAX_OPCIONES = 6;
// US-9-AC-3: una cancelación en trámite sigue apartando el horario hasta que Salud Integral la confirme.
const ACTIVOS = ['PENDIENTE', 'PENDIENTE_VALIDACION', 'CONFIRMADA', 'CANCELACION_SOLICITADA'];

const v = $('Validar consulta').first().json;
const r = $('Interpretar agenda').first().json;
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase()
  .replace(/[^A-Z0-9]+/g, ' ').trim();

// ¿No se pudo leer la agenda? En consulta se devuelve el mensaje tal cual; en verificación, no verificado.
if (!r.ok) {
  if (v.modo === 'verificar')
    return [{ json: { ok: false, verificado: false, mensaje: 'No fue posible verificar el horario en la agenda.' } }];
  return [{ json: r }];
}

// ---------- Horarios apartados por otras solicitudes ----------
function fechaISO(f) {
  if (f === '' || f == null) return '';
  if (typeof f === 'number')
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONA }).plus({ days: Math.floor(f) }).toISODate();
  const s = String(f).trim();
  for (const fmt of ['yyyy-MM-dd', 'dd/MM/yyyy', 'd/M/yyyy']) {
    const d = DateTime.fromFormat(s, fmt, { zone: ZONA });
    if (d.isValid) return d.toISODate();
  }
  return '';
}
function horaHHmm(h) {
  if (h === '' || h == null) return '';
  if (typeof h === 'number') { const m = Math.round((h % 1) * 1440); return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`; }
  const m = String(h).trim().toLowerCase().replace(/\s+/g, '').replace(/\./g, '').match(/^(\d{1,2})(?::(\d{2}))?(am|pm)?$/);
  if (!m) return '';
  let hour = +m[1]; const minute = m[2] ? +m[2] : 0;
  if (m[3] === 'pm' && hour < 12) hour += 12;
  if (m[3] === 'am' && hour === 12) hour = 0;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}
const clave = (fecha, hora, prof) => `${fecha}|${hora}|${norm(prof)}`;

const entrada = $input.all().map(x => x.json);
const errorHoja = entrada.some(f => f && f.error);
const apartados = new Set();
for (const f of entrada) {
  if (!f || !f.id) continue;
  const estado = String(f.estado ?? '').trim().toUpperCase();
  if (!ACTIVOS.includes(estado)) continue;
  const prof = f.profesional_asignado || f.profesional_solicitado;
  if (f.fecha_solicitada && f.hora_solicitada)
    apartados.add(clave(fechaISO(f.fecha_solicitada), horaHHmm(f.hora_solicitada), f.profesional_solicitado || prof));
  if (estado === 'CONFIRMADA' && f.fecha_cita && f.hora_cita)
    apartados.add(clave(fechaISO(f.fecha_cita), horaHHmm(f.hora_cita), prof));
}
const libres = r.candidatos.filter(x => !apartados.has(clave(x.fecha, x.hora, x.profesional)));
const numerar = lista => lista.slice(0, MAX_OPCIONES).map((x, n) => ({ opcion: n + 1, ...x }));

// ---------- Modo verificar (US-5) ----------
if (v.modo === 'verificar') {
  if (errorHoja)
    return [{ json: { ok: false, verificado: false, mensaje: 'No fue posible revisar las solicitudes registradas.' } }];
  const sigue = libres.some(x => x.fecha === v.desde && x.hora === v.hora_verificar &&
    (!v.profesional_verificar || norm(x.profesional) === norm(v.profesional_verificar)));
  if (sigue) return [{ json: { ok: true, verificado: true, disponible: true } }];
  const opciones = numerar(libres);
  return [{ json: { ok: true, verificado: true, disponible: false, opciones,
    mensaje: opciones.length
      ? 'El horario elegido ya no está disponible. Ofrece SOLO estas otras opciones, numeradas.'
      : 'El horario elegido ya no está disponible y no hay otros horarios libres desde esa fecha. Ofrece buscar otra fecha.' } }];
}

// ---------- Modo consultar (US-3) ----------
const opciones = numerar(libres);
// US-9-AC-1: si no hay horarios, se sugiere buscar una semana después, conservando servicio y profesional.
const fecha_sugerida = opciones.length ? '' : DateTime.fromISO(String(r.desde || ''), { zone: ZONA }).plus({ days: 7 }).toISODate() || '';
return [{ json: {
  ok: true,
  fecha_sugerida,
  servicio: r.servicio,
  desde: r.desde,
  franja: r.franja,
  profesional: r.profesional,
  profesionales: r.profesionales,
  total_libres: libres.length,
  opciones,
  mensaje: r.mensaje_sin_resultados
    ?? (opciones.length
      ? `Hay ${libres.length} horarios libres. Ofrece SOLO estas opciones, numeradas, sin inventar otras.`
      : `No hay horarios libres de ${r.servicio}${v.profesional ? ' con ' + v.profesional : ''} desde ${r.desde}${v.franja ? ' en la ' + v.franja : ''}. Dilo con claridad y ofrece: buscar desde ${fecha_sugerida || 'otra fecha'}, otra franja${v.profesional ? ' u otro profesional' : ''}. Conserva el servicio${v.profesional ? ' y el profesional' : ''}; si acepta, vuelve a usar consultar_horarios.`),
} }];

// US-5 + US-6 · Decide CÓMO se registra la solicitud, después de revalidar el horario y de leer las
// reglas de pago. Entra: las filas de la pestaña Reglas_pago (nodo "Leer reglas de pago").
// Usa también: "Preparar solicitud" (datos ya validados) y "Revalidar horario" (resultado de la verificación).
const p = $('Preparar solicitud').first().json;
const rv = $('Revalidar horario').first().json ?? {};
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, '_');

// ---------- 1. Revalidación del horario (US-5) ----------
// AC-2: si el horario dejó de estar disponible, NO se registra y se ofrecen otras opciones.
if (rv.ok === true && rv.verificado === true && rv.disponible === false)
  return [{ json: { ok: false, horario_no_disponible: true, opciones: rv.opciones ?? [],
    mensaje: rv.mensaje ?? 'El horario elegido ya no está disponible. Ofrece otras opciones.' } }];

// AC-3: si no se pudo verificar (error, agenda ilegible o no hay horario elegido), se registra
// como PENDIENTE_VALIDACION: Erika revisa el horario y nunca se comunica como confirmado.
const verificado = rv.ok === true && rv.verificado === true && rv.disponible === true;
const estado = verificado ? 'PENDIENTE' : 'PENDIENTE_VALIDACION';

// ---------- 2. Condiciones de pago (US-6) ----------
// AC-1: se busca la regla del servicio y del tipo de atención en Reglas_pago.
// AC-4: si no hay regla, o la regla no está CONFIRMADA por Salud Integral, NO se inventa nada:
//       queda POR_CONFIRMAR y Erika decide.
const reglas = $input.all().map(x => x.json).filter(r => r && r.servicio);
const deServicio = reglas.filter(r => norm(r.servicio) === norm(p.servicio));
const regla = deServicio.find(r => norm(r.tipo_atencion) === p.tipo_atencion)
  ?? deServicio.find(r => ['*', 'todas', 'todos'].includes(norm(r.tipo_atencion)));

let requiere_pago = 'POR_CONFIRMAR', estado_pago = 'POR_CONFIRMAR', valor_pago = '', instrucciones_pago = '';
if (regla && norm(regla.estado_regla) === 'confirmada') {
  const req = norm(regla.requiere_pago);
  if (req === 'no') { requiere_pago = 'NO'; estado_pago = 'NO_APLICA'; }
  else if (req === 'si' || req === 'sí') {
    requiere_pago = 'SI';
    estado_pago = 'PENDIENTE_RECIBO';           // AC-2: Erika debe generar el recibo
    valor_pago = String(regla.valor ?? '').trim();
    instrucciones_pago = String(regla.instrucciones ?? '').trim();
  }
}

return [{ json: { ...p, ok: true, estado, horario_verificado: verificado ? 'SI' : 'NO',
  requiere_pago, estado_pago, valor_pago, instrucciones_pago } }];

// US-6-AC-3 · El estudiante envió una foto o un PDF. ¿A qué solicitud con pago pendiente corresponde?
// Entra: las solicitudes de ESTE número de WhatsApp (nodo "Buscar solicitudes del estudiante").
// Se elige la más reciente que esté activa y esperando recibo o comprobante.
const ACTIVAS = ['PENDIENTE', 'PENDIENTE_VALIDACION', 'CONFIRMADA'];
const ESPERAN_COMPROBANTE = ['PENDIENTE_RECIBO', 'RECIBO_ENVIADO', 'COMPROBANTE_RECIBIDO', 'COMPROBANTE_RECHAZADO'];
const i = $('Entrada herramienta').first().json;
const tel = String(i.telefono ?? '').replace(/\D/g, '');
const mayus = v => String(v ?? '').trim().toUpperCase();

const filas = $input.all().map(x => x.json)
  .filter(f => f && f.id && String(f.telefono ?? '').replace(/\D/g, '') === tel)   // doble control del número
  .filter(f => ACTIVAS.includes(mayus(f.estado)) && ESPERAN_COMPROBANTE.includes(mayus(f.estado_pago)));

if (!filas.length)
  return [{ json: { ok: false, mensaje: 'Recibí tu archivo 📎, pero no tienes ningún pago pendiente en tus solicitudes. Si querías enviarme otra cosa, cuéntame por escrito qué necesitas.' } }];

// La más reciente: la última fila de la hoja (row_number más alto).
const f = filas.sort((a, b) => (b.row_number ?? 0) - (a.row_number ?? 0))[0];
return [{ json: {
  ok: true,
  id: f.id, nombre: f.nombre, codigo: f.codigo, numero_documento: f.numero_documento, servicio: f.servicio,
  valor_pago: f.valor_pago ?? '', reenvio: mayus(f.estado_pago) === 'COMPROBANTE_RECIBIDO', estado_pago_anterior: mayus(f.estado_pago),
  telefono: tel, message_id: i.message_id, tipo_archivo: i.mimetype || 'archivo',
