// Respuesta al estudiante después de registrar el comprobante. Deja claro que RECIBIR no es VALIDAR (US-6-AC-3).
const s = $('Elegir solicitud del pago').first().json;
return [{ json: { ok: true, id: s.id,
  mensaje: `¡Recibí tu comprobante para la solicitud *${s.id}*! 🧾 Salud Integral lo revisará y validará el pago; te aviso por aquí apenas quede listo. Por ahora tu cita todavía no está confirmada.` } }];

// US-8 · Resume las solicitudes del estudiante en lenguaje claro, con un solo criterio para todo el bot.
// AC-1: cada solicitud trae servicio, profesional, fecha y hora.
// AC-2: distingue RECIBIDA (en revisión, sin pasos pendientes), PENDIENTE (falta algo: horario por
//       verificar, pago, comprobante) y CONFIRMADA (asignada y con pago validado si aplica).
// AC-3: nunca marca CONFIRMADA una cita con pago obligatorio sin validar.
// Ahorro de tokens: el agente recibe ~8 campos por solicitud en vez de las ~40 columnas de la hoja.
const ZONA = 'America/Bogota';
const mayus = v => String(v ?? '').trim().toUpperCase();
const txt = v => String(v ?? '').trim();
const MAX_ACTIVAS = 5, MAX_CERRADAS = 3;
const FINALES = ['RECHAZADA', 'CANCELADA', 'CERRADA'];

const entrada = $input.all().map(x => x.json);
if (entrada.some(f => f && f.error))
  return [{ json: { ok: false, error_consulta: true,
    mensaje: 'No fue posible consultar las solicitudes en este momento. Dilo con honestidad, no inventes estados y pide que lo intente de nuevo en unos minutos.' } }];
const filas = entrada.filter(f => f && txt(f.id));

function fecha(v) {
  if (v === '' || v == null) return null;
  if (typeof v === 'number') return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONA }).plus({ days: Math.floor(v) });
  for (const fmt of ['yyyy-MM-dd', 'dd/MM/yyyy', 'd/M/yyyy']) {
    const d = DateTime.fromFormat(txt(v), fmt, { zone: ZONA });
    if (d.isValid) return d;
  }
  return null;
}
function hora(v) {
  if (v === '' || v == null) return '';
  if (typeof v === 'number') { const m = Math.round((v % 1) * 1440); v = `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`; }
  const m = txt(v).match(/^(\d{1,2})(?::(\d{2}))?/);
  if (!m) return txt(v);
  const h = +m[1], mi = m[2] ? +m[2] : 0;
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(mi).padStart(2, '0')} ${h < 12 ? 'a. m.' : 'p. m.'}`;
}
const cuando = (f, h) => { const d = fecha(f); return d ? d.setLocale('es').toFormat("cccc d 'de' LLLL") + (hora(h) ? `, ${hora(h)}` : '') : ''; };

/** Estado para el estudiante: el mismo criterio que la hoja (US-7) y el motor de estados. */
function estadoParaEstudiante(f) {
  const e = mayus(f.estado), p = mayus(f.estado_pago), req = mayus(f.requiere_pago);
  const pagoPendiente = req === 'SI' && p !== 'PAGO_VALIDADO';
  const motivo = txt(f.motivo_estado);
  if (e === 'CONFIRMADA' && !pagoPendiente)
    return ['CONFIRMADA', 'Cita confirmada.', 'Asistir puntual. Si no puede ir, escribir CANCELAR.'];
  if (e === 'CONFIRMADA')
    return ['PENDIENTE', 'Tiene horario asignado, pero todavía NO está confirmada: falta validar el pago.', siguientePago(p, f)];
  if (e === 'PENDIENTE' || e === 'PENDIENTE_VALIDACION') {
    if (req === 'SI' || p === 'POR_CONFIRMAR' || req === 'POR_CONFIRMAR') {
      const s = siguientePago(p, f);
      if (s) return ['PENDIENTE', 'Solicitud en trámite: hay un paso de pago pendiente.', s];
    }
    if (e === 'PENDIENTE_VALIDACION')
      return ['PENDIENTE', 'Solicitud recibida; el horario todavía está por verificar.', 'Salud Integral revisará la agenda y le avisará.'];
    return ['RECIBIDA', 'Solicitud recibida y en revisión. Todavía no es una cita confirmada.', 'Salud Integral asignará el profesional y le confirmará por este chat.'];
  }
  if (e === 'CANCELACION_SOLICITADA') return ['CANCELACION_EN_TRAMITE', 'La cancelación está en trámite.', 'Salud Integral la confirmará.'];
  if (e === 'CANCELADA') return ['CANCELADA', 'Solicitud cancelada' + (motivo ? `: ${motivo}` : '.'), 'Si necesita atención, puede hacer una solicitud nueva.'];
  if (e === 'RECHAZADA') return ['RECHAZADA', 'Salud Integral no pudo aprobar la solicitud' + (motivo ? `: ${motivo}` : '.'), 'Puede hacer una solicitud nueva si lo necesita.'];
  if (e === 'CERRADA') return ['CERRADA', 'La cita ya pasó y el proceso terminó.', ''];
  return ['RECIBIDA', 'Solicitud en revisión.', 'Salud Integral le avisará por este chat.'];
}
function siguientePago(p, f) {
  if (p === 'POR_CONFIRMAR' || p === '') return 'Salud Integral está definiendo si la atención tiene costo y le avisará.';
  if (p === 'PENDIENTE_RECIBO') return 'Salud Integral generará el recibo y lo enviará a su correo.';
  if (p === 'RECIBO_ENVIADO') return 'El recibo ya se envió a su correo. Cuando pague, enviar por este chat una foto o PDF del comprobante.';
  if (p === 'COMPROBANTE_RECIBIDO') return 'Recibimos su comprobante; Salud Integral lo está revisando.';
  if (p === 'COMPROBANTE_RECHAZADO') return 'El comprobante no se pudo validar' + (txt(f.observaciones) ? ` (${txt(f.observaciones)})` : '') + '. Enviar uno nuevo por este chat.';
  if (p === 'PAGO_VALIDADO') return 'Pago validado; falta que Salud Integral asigne y confirme la cita.';
  return '';
}

const resumen = filas.map((f, idx) => {
  const [categoria, estado_texto, siguiente_paso] = estadoParaEstudiante(f);
  const confirmada = mayus(f.estado) === 'CONFIRMADA';
  return {
    orden: idx, id: txt(f.id), servicio: txt(f.servicio), categoria, estado_texto, siguiente_paso,
    profesional: confirmada ? txt(f.profesional_asignado || f.profesional_solicitado) : txt(f.profesional_solicitado),
    profesional_es: confirmada ? 'asignado' : 'solicitado',
    cuando: confirmada ? cuando(f.fecha_cita, f.hora_cita) : cuando(f.fecha_solicitada, f.hora_solicitada),
    cuando_es: confirmada ? 'cita' : 'horario solicitado',
    final: FINALES.includes(mayus(f.estado)),
  };
});
const activas = resumen.filter(r => !r.final).sort((a, b) => b.orden - a.orden).slice(0, MAX_ACTIVAS);
const terminadas = resumen.filter(r => r.final).sort((a, b) => b.orden - a.orden).slice(0, MAX_CERRADAS);
const ultima = filas[filas.length - 1] || {};
const solicitudes = [...activas, ...terminadas].map(({ orden, final, ...r }) => r);

return [{ json: {
  ok: true,
  total: filas.length,
  solicitudes,
  datos_estudiante: filas.length ? {
    nombre: txt(ultima.nombre), codigo: txt(ultima.codigo), tipo_documento: txt(ultima.tipo_documento),
    numero_documento: txt(ultima.numero_documento), edad: txt(ultima.edad), programa: txt(ultima.programa), facultad: txt(ultima.facultad), correo: txt(ultima.correo),
  } : null,
  mensaje: filas.length
    ? 'Para informar el estado repite estado_texto y siguiente_paso de cada solicitud, con servicio, profesional y cuando. Solo di "confirmada" si categoria es CONFIRMADA.'
    : 'No tiene solicitudes registradas con este número.',
} }];

// US-8-AC-3 / US-9-AC-2 / AC-4 · Guardar solicitud falló (salida de error): no hay código ni registro.
// El borrador NO se limpia, así que el siguiente intento no vuelve a pedir los datos.
return [{ json: { ok: false, error_registro: true,
  mensaje: 'No fue posible guardar la solicitud por un problema técnico. NO digas que quedó registrada ni des un código. Explica que hubo un problema, que sus datos quedan guardados y que lo intente de nuevo en unos minutos.' } }];
